class Solution { public:
 int minOperations(string s1,string s2,int x){
  vector<int> p;for(int i=0;i<(int)s1.size();++i)if(s1[i]!=s2[i])p.push_back(i);
  int m=p.size();if(m%2)return -1;
  vector<long long> dp(m+1,0);if(m>=1)dp[1]=x;
  for(int i=2;i<=m;++i)dp[i]=min(dp[i-1]+x,dp[i-2]+2LL*(p[i-1]-p[i-2]));
  return (int)(dp[m]/2);
 }
};
